 {config.mode!=='performance'&&<button onClick={()=>setConfig(c=>({...c,benchmark:undefined,mode:'quality',testIds:snap?.tests.filter(t=>t.category==='Accounting').map(t=>t.id)??[],maxTokens:1536,preset:'Custom'}))}>Use accounting suite</button>}
